window.QV = window.QV || {};
// QV local ref merged

QV.screens.character = {
  selectedSuit: 'blue',

  render: function() {
    const suits = [
      { id: 'blue', name: 'นักบินฟ้า', image: 'suit_blue.webp', color: '#38BDF8' },
      { id: 'red', name: 'นักรบไฟ', image: 'suit_red.webp', color: '#EF4444' },
      { id: 'green', name: 'นักสำรวจใบ', image: 'suit_green.webp', color: '#6EE7B7' }
    ];

    return `
      <div class="screen-character">
        <div class="character-form">
          <h2 style="text-align: center; font-size: clamp(1.75rem, 4vw, 2.5rem); margin-bottom: 2rem; color: #fff;">
            เลือกสูทนักสำรวจ
          </h2>

          <div style="margin-bottom: 2rem;">
            <label for="player-name" style="display: block; margin-bottom: 0.5rem; font-weight: 600; color: rgba(255,255,255,0.9);">
              ชื่อของนักสำรวจ
            </label>
            <input 
              type="text" 
              id="player-name" 
              placeholder="กรอกชื่อเล่นของคุณ" 
              maxlength="20"
              style="width: 100%; padding: 0.875rem 1.25rem; border-radius: 999px; border: 2px solid rgba(255,255,255,0.1); background: rgba(255,255,255,0.05); color: #fff; font-size: 1rem; transition: all 0.3s ease;"
            />
          </div>

          <div class="suit-grid" style="display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 1rem; margin-bottom: 2rem;">
            ${suits.map(suit => `
              <div class="suit-card ${suit.id === 'blue' ? 'selected' : ''}" data-suit="${suit.id}" style="cursor: pointer; transition: transform 0.2s ease;">
                <img src="assets/${suit.image}" alt="${suit.name}" style="width: 100%; height: auto; border-radius: 12px; margin-bottom: 0.75rem;" onerror="this.src='data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22%3E%3Crect fill=%22${suit.color}%22 width=%22100%22 height=%22100%22/%3E%3Ctext x=%2250%22 y=%2255%22 font-size=%2240%22 text-anchor=%22middle%22 fill=%22white%22%3E🚀%3C/text%3E%3C/svg%3E'" />
                <h3 style="text-align: center; font-size: 1rem; font-weight: 600; color: ${suit.color}; margin: 0;">
                  ${suit.name}
                </h3>
              </div>
            `).join('')}
          </div>

          <div class="character-actions text-center">
            <button id="btn-confirm" class="btn btn-primary" style="min-width: 240px;">
              ✨ ยืนยันและออกเดินทาง
            </button>
          </div>
        </div>
      </div>
    `;
  },

  mount: function() {
    const suitCards = document.querySelectorAll('.suit-card');
    const playerNameInput = document.getElementById('player-name');
    const btnConfirm = document.getElementById('btn-confirm');

    // เลือกสูท
    suitCards.forEach(card => {
      card.addEventListener('click', () => {
        suitCards.forEach(c => c.classList.remove('selected'));
        card.classList.add('selected');
        QV.screens.character.selectedSuit = card.dataset.suit;
      });
    });

    // ยืนยันและเริ่มเกม
    if (btnConfirm) {
      btnConfirm.addEventListener('click', () => {
        const name = playerNameInput.value.trim();

        if (!name) {
          // แสดง shake animation
          playerNameInput.style.animation = 'shake 0.5s ease';
          setTimeout(() => {
            playerNameInput.style.animation = '';
          }, 500);

          QV.app.toast('กรุณากรอกชื่อก่อนนะ! 😊', 'wrong');
          playerNameInput.focus();
          return;
        }

        // บันทึกข้อมูลผู้เล่น
        QV.state.player.name = QV.escapeHtml(name.substring(0, 20));
        QV.state.player.suit = QV.screens.character.selectedSuit;
        QV.saveState(QV.state);

        // ไปหน้าแผนที่
        QV.app.show('map');
      });
    }

    // Focus ที่ช่องชื่อ
    if (playerNameInput) {
      playerNameInput.focus();
    }
  }
};

// เพิ่ม shake animation ถ้ายังไม่มี
if (!document.getElementById('shake-style')) {
  const style = document.createElement('style');
  style.id = 'shake-style';
  style.textContent = `
    @keyframes shake {
      0%, 100% { transform: translateX(0); }
      25% { transform: translateX(-10px); }
      75% { transform: translateX(10px); }
    }
  `;
  document.head.appendChild(style);
}

// js/game_state.js
// จัดการ state และความคืบหน้าของเกม
window.QV = window.QV || {};
// QV local ref merged

QV.game = {
  /**
   * ตรวจสอบและคืนค่า badge id ที่ผู้เล่นควรได้รับ
   * @param {Object} state - state ปัจจุบัน
   * @returns {Array} array ของ badge id ที่เพิ่งได้รับใหม่
   */
  checkBadgeEarns(state) {
    const newBadges = [];
    const currentBadges = state.badges || [];

    // explorer-{planetId}: ผ่านโซนใน planet นั้นครบ 5 โซน
    QV.planets.forEach(planet => {
      const badgeId = `explorer-${planet.id}`;
      const planetState = state.planets[planet.id];
      if (planetState && planetState.zonesDone && planetState.zonesDone.length >= 5) {
        if (!currentBadges.includes(badgeId)) {
          newBadges.push(badgeId);
          currentBadges.push(badgeId);
        }
      }
    });

    // combo-master: maxCombo >= 10
    if (state.maxCombo >= 10 && !currentBadges.includes('combo-master')) {
      newBadges.push('combo-master');
      currentBadges.push('combo-master');
    }

    // globe-trotter: ครบ 5 ดาวที่มี zonesDone >= 5
    let planetsCompleted = 0;
    QV.planets.forEach(planet => {
      const planetState = state.planets[planet.id];
      if (planetState && planetState.zonesDone && planetState.zonesDone.length >= 5) {
        planetsCompleted++;
      }
    });
    if (planetsCompleted >= 5 && !currentBadges.includes('globe-trotter')) {
      newBadges.push('globe-trotter');
      currentBadges.push('globe-trotter');
    }

    // universe-conqueror: ผ่านโซนรวมครบ 25 โซน
    let totalZones = 0;
    QV.planets.forEach(planet => {
      const planetState = state.planets[planet.id];
      if (planetState && planetState.zonesDone) {
        totalZones += planetState.zonesDone.length;
      }
    });
    if (totalZones >= 25 && !currentBadges.includes('universe-conqueror')) {
      newBadges.push('universe-conqueror');
      currentBadges.push('universe-conqueror');
    }

    // speed-runner: ตอบถูกภายใน 5 วินาที >= 10 ครั้ง
    if (state.fastCorrect5s >= 10 && !currentBadges.includes('speed-runner')) {
      newBadges.push('speed-runner');
      currentBadges.push('speed-runner');
    }

    state.badges = currentBadges;
    return newBadges;
  },

  /**
   * เพิ่ม XP และตรวจสอบการขึ้นยศและ badge
   * @param {Object} state - state ปัจจุบัน
   * @param {number} amount - จำนวน XP ที่จะเพิ่ม
   * @param {number} questionStartTs - timestamp เริ่มตอบคำถาม (ms)
   * @returns {Object} { newRank, rankUp, badgesNew }
   */
  addXp(state, amount, questionStartTs) {
    const oldRank = QV.getRank(state.xp);
    state.xp += amount;
    const newRank = QV.getRank(state.xp);
    const rankUp = newRank.index > oldRank.index;

    // ตรวจสอบเวลาตอบ
    if (questionStartTs) {
      const answerTime = (Date.now() - questionStartTs) / 1000;
      if (answerTime <= 5) {
        state.fastCorrect5s = (state.fastCorrect5s || 0) + 1;
      }
    }

    const badgesNew = this.checkBadgeEarns(state);

    return { newRank, rankUp, badgesNew };
  },

  /**
   * ทำเครื่องหมายโซนเสร็จสมบูรณ์
   * @param {Object} state - state ปัจจุบัน
   * @param {string} planetId - id ของดาว
   * @param {number} zoneIdx - index ของโซน
   * @param {number} correctCount - จำนวนข้อที่ตอบถูก
   * @returns {Array} badge id ที่เพิ่งได้รับใหม่
   */
  completeZone(state, planetId, zoneIdx, correctCount) {
    const planetState = state.planets[planetId];
    if (!planetState) return [];

    // เพิ่มโซนที่เสร็จแล้ว
    if (!planetState.zonesDone.includes(zoneIdx)) {
      planetState.zonesDone.push(zoneIdx);
    }

    // เพิ่ม energy คืนหนึ่งหัวใจต่อการผ่านโซน
    state.energy = Math.min(state.energy + 1, QV.MAX_ENERGY);

    // ตั้งค่า currentZone ถัดไป
    planetState.currentZone = zoneIdx + 1;

    // ตรวจสอบ badge
    return this.checkBadgeEarns(state);
  },

  /**
   * ใช้ไอเทม
   * @param {Object} state - state ปัจจุบัน
   * @param {string} itemId - id ของไอเทม
   * @returns {boolean} สำเร็จหรือไม่
   */
  useItem(state, itemId) {
    if (state.items[itemId] && state.items[itemId] > 0) {
      state.items[itemId]--;
      return true;
    }
    return false;
  },

  /**
   * คืนสถานะของโซน
   * @param {Object} planet - ข้อมูลดาว
   * @param {number} zoneIdx - index ของโซน
   * @param {Object} planetState - state ของดาว
   * @returns {string} "done" | "active" | "locked"
   */
  zoneStatus(planet, zoneIdx, planetState) {
    if (!planetState) return 'locked';

    // โซนที่ทำเสร็จแล้ว
    if (planetState.zonesDone.includes(zoneIdx)) {
      return 'done';
    }

    // โซนแรกปลดล็อกเสมอ
    if (zoneIdx === 0) {
      return 'active';
    }

    // โซนถัดไปปลดล็อกเมื่อโซนก่อนหน้าเสร็จ
    if (planetState.zonesDone.includes(zoneIdx - 1)) {
      return 'active';
    }

    return 'locked';
  },

  /**
   * จำนวนการเล่น minigame ที่เหลือในวันนี้ (ฟรี 3 ครั้ง/วัน)
   */
  minigameRemaining(state) {
    const todayKey = QV.todayKey();
    const count = (state.minigamePlays && state.minigamePlays[todayKey]) || 0;
    return Math.max(0, 3 - count);
  },

  /**
   * จำนวนครั้งที่เล่น minigame ไปแล้ววันนี้
   */
  getMiniGamePlays(state) {
    const todayKey = QV.todayKey();
    return (state.minigamePlays && state.minigamePlays[todayKey]) || 0;
  },

  /**
   * บันทึกผล minigame และมอบรางวัล (ชนะ: +1 ใจ +30 XP / แพ้: +10 XP)
   */
  minigamePlay(state, won) {
    const todayKey = QV.todayKey();
    state.minigamePlays = state.minigamePlays || {};
    state.minigamePlays[todayKey] = (state.minigamePlays[todayKey] || 0) + 1;
    if (won) {
      state.energy = Math.min(state.energy + 1, QV.MAX_ENERGY);
      state.xp += 30;
    } else {
      state.xp += 10;
    }
    return this.checkBadgeEarns(state);
  }
};

// js/galaxy_map.js
// หน้าแผนที่กาแล็กซี่
window.QV = window.QV || {};
// QV local ref merged

QV.screens.map = {
  render() {
    const state = QV.state;
    const currentRank = QV.getRank(state.xp);

    // หา threshold ยศถัดไปจาก QV.ranks ของ config.js
    const nextRank = QV.ranks[currentRank.index + 1];
    const nextThreshold = nextRank ? nextRank[0] : state.xp || 1;
    const xpBase = currentRank.index > 0 ? QV.ranks[currentRank.index][0] : 0;
    const xpPercent = nextRank ? Math.min(100, ((state.xp - xpBase) / (nextThreshold - xpBase)) * 100) : 100;
    const nextRankName = nextRank ? `${nextRank[2]} ${nextRank[1]}` : 'ยศสูงสุด';

    // สร้าง HTML แถบสถานะผู้เล่น
    const playerStatusHtml = `
      <div class="player-status">
        <div class="player-info">
          <img src="assets/suit_${state.player.suit}.webp" alt="ชุดอวกาศ" width="64" height="64" style="border-radius:50%;">
          <div class="player-name">${QV.escapeHtml(state.player.name)}</div>
        </div>
        <div class="rank-chip">
          ${currentRank.emoji} ${currentRank.name}
        </div>
        <div class="xp-bar-container">
          <div class="xp-bar-label">XP ${QV.formatNumber(state.xp)} → ${nextRankName} ที่ ${QV.formatNumber(nextThreshold)}</div>
          <div class="xp-bar">
            <div class="xp-bar-fill" style="width: ${xpPercent}%"></div>
          </div>
        </div>
        <div class="energy-hearts">
          ${Array.from({ length: QV.MAX_ENERGY }, (_, i) => {
            return `<span class="heart${i < state.energy ? '' : ' empty'}">${i < state.energy ? '❤️' : '🤍'}</span>`;
          }).join('')}
          ${state.energy <= 0 && QV.game.minigameRemaining(state) > 0 ? `<button class="btn btn-item" id="btn-map-minigame" style="margin-left: 8px;">⚡ ฟื้นพลังงาน</button>` : ''}
        </div>
      </div>
    `;

    // สร้าง planet cards
    const planetsHtml = QV.planets.map(planet => {
      const planetState = state.planets[planet.id];
      const isPlanetLocked = this._isPlanetLocked(planet.id, state);
      const zonesDoneCount = planetState ? planetState.zonesDone.length : 0;
      const currentZone = planetState ? planetState.currentZone : 0;

      let statusClass = 'locked';
      let statusText = '🔒 ต้องปลดดาวก่อน';

      if (!isPlanetLocked) {
        if (zonesDoneCount >= planet.zoneCount) {
          statusClass = 'complete';
          statusText = '✅ ดาวพิชิตแล้ว!';
        } else {
          statusClass = 'active';
          statusText = `🚀 โซนที่ ${currentZone + 1}/${planet.zoneCount}`;
        }
      }

      return `
        <div class="planet-card ${isPlanetLocked ? 'locked' : ''}" data-planet-id="${planet.id}">
          <img src="${planet.image}" alt="${planet.name}" class="planet-image">
          <div class="planet-name">${planet.name}</div>
          <div class="planet-desc">${planet.desc}</div>
          <div class="planet-subject" style="background-color: ${planet.themeColor}20; color: ${planet.themeColor};">
            ${planet.subject}
          </div>
          <div class="planet-status ${statusClass}">
            ${statusText}
          </div>
        </div>
      `;
    }).join('');

    // ===== ส่วนท้าบอส =====
    const bossDefeated = Array.isArray(state.bossDefeated) ? state.bossDefeated : [];
    const bossDefs = [
      { id: 'mathos', name: 'Mathos the Calculator', img: 'assets/boss_mathos.webp', tag: 'บอสพิชคณิต • 10 คำถาม • XP 200' },
      { id: 'chronos', name: 'Chronos the Timekeeper', img: 'assets/boss_chronos.webp', tag: 'บอสแห่งเวลา • 10 คำถาม • XP 200' }
    ];
    const bossCardsHtml = bossDefs.map(boss => {
      const defeated = bossDefeated.includes(boss.id);
      return `
        <div class="boss-card">
          ${defeated ? '<div class="boss-defeated-stamp">✅ พิชิตแล้ว</div>' : ''}
          <img src="${boss.img}" alt="${boss.name}" class="boss-img">
          <div class="boss-info">
            <div class="boss-name">${boss.name}</div>
            <div class="boss-tag">${boss.tag}</div>
            <button class="boss-challenge-btn" data-boss="${boss.id}" id="btn-map-boss-${boss.id}">
              ${defeated ? '🔁 ท้าชิงต่อ' : '⚔️ ท้าประจัญ!'}
            </button>
          </div>
        </div>
      `;
    }).join('');
    const bossSectionHtml = `
      <div class="boss-section">
        ${bossCardsHtml}
      </div>
    `;

    return `
      <div class="screen-map">
        <div class="map-header">
          <h2>แผนที่กาแล็กซี่</h2>
          <div class="map-actions">
            <button class="btn btn-secondary" id="btn-map-lb">🏆 กระดานผู้นำ</button>
            <button class="btn btn-secondary" id="btn-reset">🔄 รีสตาร์ตเกม</button>
          </div>
        </div>
        ${playerStatusHtml}
        <div class="planets-grid">
          ${planetsHtml}
        </div>
        ${bossSectionHtml}
      </div>
    `;
  },

  mount() {
    const state = QV.state;

    // ปุ่มกระดานผู้นำ
    const btnLb = document.getElementById('btn-map-lb');
    if (btnLb) {
      btnLb.addEventListener('click', () => {
        QV.app.show('leaderboard');
      });
    }
    // ปุ่มฟื้นพลังงานจากมินิเกม (แสดงเฉพาะ energy <= 0)
    const btnMg = document.getElementById('btn-map-minigame');
    if (btnMg) btnMg.addEventListener('click', () => QV.app.show('minigame'));

    // ปมท้าบอส (Mathos / Chronos)
    ['mathos', 'chronos'].forEach(bossId => {
      const btnBoss = document.getElementById('btn-map-boss-' + bossId);
      if (btnBoss) {
        btnBoss.addEventListener('click', (e) => {
          e.stopPropagation();
          QV.app.show('boss', { boss: bossId });
        });
      }
    });

    // ปุ่ม reset
    const btnReset = document.getElementById('btn-reset');
    if (btnReset) {
      btnReset.addEventListener('click', () => {
        if (confirm('คุณแน่ใจหรือไม่ว่าต้องการออกจากระบบและรีสตาร์ตเกม? ข้อมูลทั้งหมดจะถูกลบ')) {
          localStorage.clear();
          location.reload();
        }
      });
    }

    // คลิก planet card
    const planetCards = document.querySelectorAll('.planet-card');
    planetCards.forEach(card => {
      const planetId = card.getAttribute('data-planet-id');
      const isLocked = card.classList.contains('locked');

      if (!isLocked) {
        card.style.cursor = 'pointer';
        card.addEventListener('click', () => {
          // บันทึก planetId ที่เลือกไว้ใน state ชั่วคราว
          QV.currentPlanetId = planetId;
          QV.app.show('mission');
        });
      }
    });

    // อัปเดตแถบสถานะ
    QV.app.updatePlayerStatus();
  },

  /**
   * ตรวจสอบว่าดาวถูกล็อกหรือไม่
   * @param {string} planetId - id ของดาว
   * @param {Object} state - state ปัจจุบัน
   * @returns {boolean}
   */
  _isPlanetLocked(planetId, state) {
    // ดาวแรก (numberon) ปลดล็อกเสมอ
    if (planetId === 'numberon') return false;

    // หา index ของดาวปัจจุบัน
    const currentPlanetIndex = QV.planets.findIndex(p => p.id === planetId);
    if (currentPlanetIndex === -1) return true;

    // ตรวจสอบดาวก่อนหน้า
    if (currentPlanetIndex > 0) {
      const prevPlanet = QV.planets[currentPlanetIndex - 1];
      const prevPlanetState = state.planets[prevPlanet.id];

      // ดาวก่อนหน้าต้องผ่านอย่างน้อย 1 โซน (จบโซนแรกก็ปลดดาวถัดไปได้ เพื่อความสนุก ไม่ต้องรอครบ 5 โซน)
      if (!prevPlanetState || prevPlanetState.zonesDone.length < 1) {
        return true;
      }
    }

    return false;
  }
};

